import React, { useEffect, useState } from "react";
import { v4 as uuidv4 } from 'uuid';
import { Question, Message, DomainStatus } from './types';

// Bileşenleri doğru yollardan import ettiğinizden emin olun
// import Header from './components/Header';
// import ChatPanel from './components/ChatPanel';
// import Sidebar from './components/Sidebar';

// --- GEÇİCİ BİLEŞEN TANIMLARI (Doğru importları yapana kadar) ---
// Projenizde bu bileşenlerin 'src/components/' altında olduğundan emin olun.
const Header: React.FC = () => <header className="h-[60px] bg-[#1e1e3f] border-b border-[#2d2d5f] text-center p-4">Header</header>;
const ChatPanel: React.FC<{ messages: Message[], onSendMessage: (prompt: string) => void, isLoading: boolean }> = ({isLoading}) => <main className="flex-1 bg-[#1a1a2e] text-center p-4">{isLoading ? 'Loading...' : 'Chat Panel'}</main>;
const Sidebar: React.FC<{ statuses: DomainStatus[], overallScore: number }> = () => <aside className="w-[400px] bg-[#1e1e3f] text-center p-4">Sidebar</aside>;
// --- GEÇİCİ BİLEŞEN TANIMLARI SONU ---


const App: React.FC = () => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionId, setCurrentQuestionId] = useState<number | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
  const [overallScore, setOverallScore] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  useEffect(() => {
    fetch("http://localhost:3001/questions")
      .then((res) => res.json())
      .then((data: Question[]) => {
        setQuestions(data);
        if (data.length > 0) {
          const firstQuestion = data[0];
          setCurrentQuestionId(firstQuestion.id);
          setMessages([{
            id: uuidv4(),
            sender: 'AI',
            text: 'Welcome! Let\'s start the assessment.',
            type: 'question',
            question: firstQuestion,
          }]);

          // Domain durumlarını başlangıçta ayarla
          const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))].map(domainName => ({
            name: domainName,
            status: domainName === firstQuestion.domain_name ? 'In Progress' : 'Pending',
            score: 0,
          }));
          setDomainStatuses(initialDomains);
        }
      })
      .catch((err) => console.error("Error fetching questions:", err))
      .finally(() => setIsLoading(false));
  }, []);

  const handleSendMessage = async (prompt: string) => {
    if (!currentQuestionId || isLoading) return;
    setIsLoading(true);

    const userMessage: Message = {
      id: uuidv4(),
      sender: 'User',
      text: prompt,
      type: 'user_response'
    };
    setMessages(prev => [...prev, userMessage]);

    try {
      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, previous_question_id: currentQuestionId }),
      });

      if (!res.ok) {
        throw new Error(`API error: ${res.statusText}`);
      }

      const apiResponse = await res.json();
      
      const taskMessage: Message = {
          id: uuidv4(),
          sender: 'AI',
          text: apiResponse.task || "No task was generated.",
          type: 'task_confirmation'
      };

      const answeredQuestion = questions.find(q => q.id === currentQuestionId);
      const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);

      // Skorları ve domain durumlarını güncelle
      if (answeredQuestion) {
        setDomainStatuses(prevStatuses => {
            const newStatuses = prevStatuses.map(status => {
                let updatedStatus = { ...status };

                // Cevaplanan domain'in skorunu güncelle
                if (status.name === answeredQuestion.domain_name) {
                    const domainQuestions = questions.filter(q => q.domain_name === status.name);
                    const questionWeight = 100 / (domainQuestions.length || 1);
                    const newScore = Math.min(100, status.score + (apiResponse.score / 100) * questionWeight);
                    
                    updatedStatus.score = newScore;

                    // Eğer bu domain'den bir sonraki soru yoksa veya sonraki soru farklı bir domaindeyse, bu domain'i 'Complete' yap
                    const domainIsFinished = !nextQuestion || nextQuestion.domain_name !== status.name;
                    if(domainIsFinished) {
                        updatedStatus.status = 'Complete';
                    }
                }

                // Bir sonraki domain'i 'In Progress' yap
                if (nextQuestion && status.name === nextQuestion.domain_name && status.status === 'Pending') {
                    updatedStatus.status = 'In Progress';
                }

                return updatedStatus;
            });

            // Genel skoru yeniden hesapla
            const totalScore = newStatuses.reduce((acc, curr) => acc + curr.score, 0);
            setOverallScore(totalScore / (newStatuses.length || 1));
            
            return newStatuses;
        });
      }

      // Bir sonraki mesajları ayarla
      if (nextQuestion) {
        const nextQuestionMessage: Message = {
          id: uuidv4(),
          sender: 'AI',
          text: 'Here is the next question.',
          type: 'question',
          question: nextQuestion,
          ai_comment: apiResponse.comment 
        };
        setMessages(prev => [...prev, taskMessage, nextQuestionMessage]);
        setCurrentQuestionId(apiResponse.next_question_id);
      } else {
        // Test bitti.
        const endMessage: Message = {
            id: uuidv4(),
            sender: 'AI',
            text: '🎉 Assessment complete! Thank you for your responses.',
            type: 'question'
        };
        setMessages(prev => [...prev, taskMessage, endMessage]);
        setCurrentQuestionId(null);
      }
      
    } catch (err) {
      console.error("Error sending message:", err);
      setMessages(prev => [...prev, { id: uuidv4(), sender: 'AI', text: "Sorry, an error occurred while processing your request.", type: 'error' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen overflow-hidden flex flex-col">
      <Header />
      <div className="flex flex-1 overflow-hidden">
        <ChatPanel messages={messages} onSendMessage={handleSendMessage} isLoading={isLoading} />
        <Sidebar statuses={domainStatuses} overallScore={overallScore} />
      </div>
    </div>
  );
};

export default App;
